# Independently generated by rrpack 0.1-14. See data/lowrank/README.md.
function _lowrank_golden_csv(name)
  rows = [parse.(Float64, split(line, ',')) for line in eachline(joinpath(@__DIR__,"data","lowrank",name))]
  reduce(vcat, permutedims.(rows))
end
@testset "rrpack golden low-rank fits" begin
  for case in 1:3
    X,Y = _lowrank_golden_csv("X$case.csv"),_lowrank_golden_csv("Y$case.csv")
    df = vec(_lowrank_golden_csv("df-$case.csv"))
    for r in 1:3
      s = reduced_rank(X,Y,r;intercept=false)
      reference = _lowrank_golden_csv("rrr-$case-$r.csv")
      if case == 3
        @test X*s.B ≈ X*reference atol=2e-9 rtol=2e-9
        @test norm(s.B) <= norm(reference)+2e-9
      else
        @test s.B ≈ reference atol=2e-9 rtol=2e-9
      end
      @test s.df_exact ≈ df[r] atol=2e-8 rtol=2e-8
    end
    case == 3 && continue
    for λ in (0.01,0.05,0.2), adaptive in (false,true)
      s = sparse_reduced_rank(X,Y,2,λ;intercept=false,adaptive,tol=1e-10,inner_tol=1e-11)
      @test s.converged
      @test s.B ≈ _lowrank_golden_csv("srrr-$case-$λ-$adaptive.csv") atol=1e-7 rtol=1e-7
    end
    ss = sparse_svd_regression(X,Y,2;intercept=false,nλ=10,tol=1e-10,inner_tol=1e-11)
    @test ss.solution.B ≈ _lowrank_golden_csv("rssvd-$case.csv") atol=1e-7 rtol=1e-7
  end
end
